package org.sleepwell.app;
import android.app.*;import android.os.*;import android.widget.*;
/** Explicit delay choice only. Saving never starts a service, sensor or microphone. */
public final class TrackingDelayActivity extends Activity {
 TrackingDelayRuntime.Job job;TrackingDelayRuntime.State drawn;int draft;boolean changed,resumed;final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle b){super.onCreate(b);RecordUi.review(this);job=TrackingDelayRuntime.get(this);if(b!=null){draft=b.getInt("draft");changed=b.getBoolean("changed");}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);render();}
 static String label(int minutes){return minutes==0?"Off":minutes+" min";}
 void render(){TrackingDelayRuntime.State s=job.state;drawn=s;if(!changed)draft=s.minutes;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Manual start delay",this::finish);Design.space(body,16);Design.text(body,"Give yourself time to settle before recording begins.",16,400,Design.MUTED);Design.space(body,18);for(int row=0;row<3;row++){LinearLayout line=Design.row(this);line.setBaselineAligned(false);line.setGravity(android.view.Gravity.TOP);for(int col=0;col<2;col++){int minutes=TrackingDelay.CHOICES[row*2+col];Button button=Design.button(line,label(minutes),draft==minutes,()->{draft=minutes;changed=true;render();});button.setSelected(draft==minutes);button.setEnabled(!s.busy);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,Design.dp(this,58),1);lp.setMargins(col==0?0:Design.dp(this,8),0,0,Design.dp(this,8));button.setLayoutParams(lp);}body.addView(line);}Design.space(body,12);Design.text(body,"Applies only when you tap Manual Start. Automatic and nightly schedules keep their own timing.",13,400,Design.MUTED);Design.space(body,12);Design.text(body,"No movement, light or sound is recorded during the wait. You can cancel or start now. If Android ends the service, start again explicitly.",13,400,Design.MUTED);if(s.plan!=null){Design.space(body,20);PlanActivity.detail(body,"clock","Last delayed start",s.plan.status(),null,null);if(s.plan.session>0)Design.text(body,"Saved recording #"+s.plan.session,12,400,Design.MUTED);if(!s.plan.issue.isEmpty())Design.text(body,s.plan.issue,13,500,Design.BROWN);}LinearLayout footer=RecordUi.footer(body);if(!s.error.isEmpty())Design.text(footer,s.error,13,500,Design.BROWN);if(s.busy)Design.text(footer,"Saving delay…",13,400,Design.MUTED);Button save=Design.button(footer,"Save start delay",true,()->{job.preference(draft);changed=false;render();});save.setEnabled(!s.busy);}
 final Runnable poll=new Runnable(){public void run(){if(!resumed)return;if(drawn!=job.state)render();main.postDelayed(this,100);}};
 @Override protected void onResume(){super.onResume();resumed=true;job.inspect(TrackingService::holdsDelayJournal,TrackingDndRuntime.boot(this));poll.run();}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}@Override public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("draft",draft);b.putBoolean("changed",changed);}@Override protected void onDestroy(){main.removeCallbacks(poll);super.onDestroy();}@Override public void onWindowFocusChanged(boolean yes){super.onWindowFocusChanged(yes);if(yes)RecordUi.lightBars(this);}
}
